import{_ as a,c as r,o,a0 as e}from"./chunks/framework.DE5X-pmd.js";const p=JSON.parse('{"title":"🧑‍🎓 学生使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"指南/student.md","filePath":"指南/student.md"}'),l={name:"指南/student.md"};function n(i,t,s,h,c,d){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="🧑‍🎓-学生使用指南" tabindex="-1">🧑‍🎓 学生使用指南 <a class="header-anchor" href="#🧑‍🎓-学生使用指南" aria-label="Permalink to &quot;🧑‍🎓 学生使用指南&quot;">​</a></h1><h2 id="一、访问平台" tabindex="-1">一、访问平台 <a class="header-anchor" href="#一、访问平台" aria-label="Permalink to &quot;一、访问平台&quot;">​</a></h2><p>打开浏览器（推荐 Chrome 或 Edge），在地址栏输入<strong>老师给你的网址</strong>。</p><blockquote><p>例如：<code>http://192.168.x.x</code> 或 <code>http://codenova.cn</code></p></blockquote><hr><h2 id="二、登录" tabindex="-1">二、登录 <a class="header-anchor" href="#二、登录" aria-label="Permalink to &quot;二、登录&quot;">​</a></h2><ol><li>在首页点击 <strong>「登录」</strong> 按钮</li><li>输入老师给你的<strong>账号和密码</strong></li><li>点击登录，进入个人主页</li></ol><hr><h2 id="三、scratch-课堂" tabindex="-1">三、Scratch 课堂 <a class="header-anchor" href="#三、scratch-课堂" aria-label="Permalink to &quot;三、Scratch 课堂&quot;">​</a></h2><p>在首页点击老师名字，进入课程页面：</p><ul><li><strong>查看素材</strong>：点击课程名，浏览本节课的课件素材</li><li><strong>打开案例</strong>：点击课件中的 <code>.sb3</code> 文件，直接在 Scratch 编辑器中打开</li></ul><h3 id="自由创作" tabindex="-1">自由创作 <a class="header-anchor" href="#自由创作" aria-label="Permalink to &quot;自由创作&quot;">​</a></h3><p>点击 <strong>「自由创作」</strong> 进入 Scratch 编辑器，可以：</p><ul><li>自由搭建积木，创作动画和游戏</li><li>点击 <strong>「文件 → 保存到电脑」</strong> 下载作品</li><li>下次上课可以上传继续编辑</li></ul><hr><h2 id="四、学习文档" tabindex="-1">四、学习文档 <a class="header-anchor" href="#四、学习文档" aria-label="Permalink to &quot;四、学习文档&quot;">​</a></h2><p>首页的 <strong>「学习文档」</strong> 区域可以查阅：</p><ul><li><strong>Scratch 课程</strong> — 图形化编程入门</li><li><strong>Python 课程</strong> — 从语法到算法</li><li><strong>C++ 课程</strong> — 从基础到竞赛</li></ul><p>每个课程都有图文并茂的教程和代码示例。</p><hr><h2 id="五、个人中心" tabindex="-1">五、个人中心 <a class="header-anchor" href="#五、个人中心" aria-label="Permalink to &quot;五、个人中心&quot;">​</a></h2><p>登录后点击 <strong>「个人中心」</strong> 可以查看：</p><ul><li>个人资料（头像、姓名）</li><li>学习记录（课堂出勤和学习内容）</li><li>收到的消息（老师的通知和反馈）</li></ul><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：忘了密码怎么办？</strong> A：联系你的老师重置密码。</p><p><strong>Q：家里的电脑可以用吗？</strong> A：可以，只要和老师在同一个网络（同一个 Wi-Fi 或教室网络），打开浏览器输入地址就行。</p><p><strong>Q：作品存在哪里？</strong> A：作品保存在你的个人空间里，每次上课都能看到。</p>',28)])])}const g=a(l,[["render",n]]);export{p as __pageData,g as default};
